package store

import (
	"context"
	"encoding/base32"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

// maxPermitAttempts bounds how many times a permit code may be presented
// before it is locked out, limiting offline-style guessing through the API.
const maxPermitAttempts = 6

// PermitStore persists first-run passkey enrollment permits. A permit is a
// short-lived, single-use authorization generated by the local CLI; it is not
// a login credential. Only its SHA-256 digest is stored.
type PermitStore struct {
	pool *pgxpool.Pool
}

// Create issues a permit for the user and returns the raw code exactly once.
// The code is formatted XXXX-XXXX-XXXX-XXXX (80 bits of entropy).
func (s *PermitStore) Create(ctx context.Context, userID uuid.UUID, ttl time.Duration) (code string, id uuid.UUID, expiresAt time.Time, err error) {
	raw := randomBytes(10)
	code = formatPermitCode(base32.StdEncoding.EncodeToString(raw))
	id = newUUID()
	err = s.pool.QueryRow(ctx,
		`INSERT INTO enrollment_permits (id, user_id, code_hash, expires_at)
		 VALUES ($1, $2, $3, now() + make_interval(secs => $4))
		 RETURNING expires_at`,
		id, userID, sha256Sum([]byte(code)), ttl.Seconds(),
	).Scan(&expiresAt)
	if err != nil {
		return "", uuid.Nil, time.Time{}, err
	}
	return code, id, expiresAt, nil
}

// BeginAttempt atomically consumes one attempt of a still-valid permit and
// returns its id and owning user. It returns ErrPermitInvalid when the code
// is unknown, expired, already used, or out of attempts.
func (s *PermitStore) BeginAttempt(ctx context.Context, code string) (id, userID uuid.UUID, err error) {
	err = s.pool.QueryRow(ctx,
		`UPDATE enrollment_permits
		 SET attempts = attempts + 1
		 WHERE code_hash = $1
		   AND used_at IS NULL
		   AND expires_at > clock_timestamp()
		   AND attempts < $2
		 RETURNING id, user_id`,
		sha256Sum([]byte(code)), maxPermitAttempts,
	).Scan(&id, &userID)
	if err != nil {
		return uuid.Nil, uuid.Nil, ErrPermitInvalid
	}
	return id, userID, nil
}

// Claim atomically marks a permit used. It returns ErrPermitUsed when the
// permit was already consumed by a completed registration.
//
// Enrollment completion now runs through Store.CompleteEnrollment, which
// consumes the permit inside its transaction; Claim remains for callers that
// need the standalone consume check.
func (s *PermitStore) Claim(ctx context.Context, id uuid.UUID) error {
	tag, err := s.pool.Exec(ctx,
		`UPDATE enrollment_permits SET used_at = now() WHERE id = $1 AND used_at IS NULL AND expires_at > now()`, id)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return ErrPermitUsed
	}
	return nil
}

func formatPermitCode(encoded string) string {
	encoded = strings.TrimRight(encoded, "=")
	var parts []string
	for i := 0; i < len(encoded); i += 4 {
		parts = append(parts, encoded[i:i+4])
	}
	return strings.Join(parts, "-")
}
